const EXPORT_BUDGET = 1_500;
const INVERTER_BUDGET = 400;

export function thinReadings(byInverter: Map<string, Reading[]>): ThinnedExport {
  const thinned: string[] = [];
  let readings = [...byInverter].flatMap(([inverterId, series]) => {
    if (series.length <= INVERTER_BUDGET) return series;
    thinned.push(inverterId);
    const stride = Math.ceil(series.length / INVERTER_BUDGET);
    return series.filter((_, index) => index % stride === 0);
  });
  if (readings.length > EXPORT_BUDGET) {
    readings = readings.slice(0, EXPORT_BUDGET);
    thinned.push("(whole export)");
  }
  return { readings, thinned };
}

