// Flag strings that are shaded rather than faulty: compare each string's output with the
// median of its array, and if it is more than ~10% lower for the whole hour, flag it.
// A fault drops a string to near zero; shade only trims it.

code_before:
export type StringHour = {
  readonly stringId: string;
  readonly meanWatts: number;
};

const SHADE_MARGIN_W = 50;

code_after:
export function shadedStrings(hour: readonly StringHour[]): string[] {
  if (hour.length < 3) return [];
  const sorted = hour.map((s) => s.meanWatts).sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  return hour
    .filter((s) => {
      const shortfall = median - s.meanWatts;
      const nearZero = s.meanWatts < median * 0.05;
      return !nearZero && shortfall > SHADE_MARGIN_W;
    })
    .map((s) => s.stringId);
}

