/// The board's column sizing, as arithmetic a test can hold.
///
/// Forty departures in one column run off the bottom of the screen, so the
/// board lays its rows out in as many columns as the width allows: one on a
/// stop's small portrait screen, two on the standard landscape one, three on
/// the wide screens at interchanges.

code_after:
enum BoardLayout {
    /// The narrowest a column may be before the board drops one: room for the
    /// route number, a destination and the minutes.
    static let minColumnWidth: CGFloat = 560
    /// Gap between columns.
    static let spacing: CGFloat = 24
    /// Padding around the whole board.
    static let outerPadding: CGFloat = 32

    /// How many columns of at least ``minColumnWidth`` fit in `width`, with
    /// ``spacing`` between them and ``outerPadding`` either side. Never fewer
    /// than one: a screen too narrow for a whole column still draws one.
    static func columns(forWidth width: CGFloat) -> Int {
        let available = width - outerPadding * 2
        guard available > 0 else { return 1 }
        // n columns fit when n × minColumnWidth + (n − 1) × spacing ≤ available.
        return max(Int((available + spacing) / (minColumnWidth + spacing)), 1)
    }
}

