export function splitSection(layout: Layout, blockIndex: number, section: SectionId, name: string): Layout {
  const block = layout.blocks[blockIndex];
  if (block === undefined) return { ...layout, blocks: [...layout.blocks] };
  if (block.sections.length <= 1) return { ...layout, blocks: [...layout.blocks] };
  if (!block.sections.includes(section)) return { ...layout, blocks: [...layout.blocks] };
  if (name.trim() === '') return { ...layout, blocks: [...layout.blocks] };

  const remaining: Block = { ...block, sections: block.sections.filter((s) => s !== section) };
  const split: Block = { name: name.trim(), sections: [section], occupied: false };
  const blocks = layout.blocks.map((b, index) => (index === blockIndex ? remaining : b));
  blocks.push(split);
  return { ...layout, blocks };
}

