async function runPostBoot(ctx: BootContext, layout: LayoutConfig): Promise<boolean> {
  const { postBootScript, folder } = layout;
  if (postBootScript === '') return true;
  ctx.out.info(`Running post-boot script in ${folder}: ${postBootScript}`);
  // passthrough: the script is the operator's own, usually setting lights and
  // sound, and its output is the only way to see what it did or why it failed.
  const { code } = await ctx.shell.run('sh', ['-c', postBootScript], { cwd: folder, passthrough: true });
  if (code === 0) return true;
  ctx.out.warn(`post-boot script exited with ${code}; the layout is up but may not be lit`);
  return false;
}

